// Terminal color themes of the `theme` option: the Ghostty default plus every theme file that
// ships with Ghostty (themes-data.js, generated by tools/gen-themes.py).
import { THEME_DATA } from "./themes-data.js";
import { mix } from "./color.js";

const names = ["black", "red", "green", "yellow", "blue", "magenta", "cyan", "white"];

// colors: 16 hex strings, normal then bright.
function theme(background, foreground, cursor, selectionBackground, colors, selectionForeground = foreground) {
  const palette = {};
  names.forEach((n, i) => {
    palette[n] = colors[i];
    palette[`bright${n[0].toUpperCase()}${n.slice(1)}`] = colors[i + 8];
  });
  return { background, foreground, cursor, cursorAccent: background, selectionBackground, selectionForeground, ...palette };
}

// The default theme is the empty name, as in the Ghostty config.
const DEFAULT = theme("#282c34", "#ffffff", "#c5c8c6", "#4a5160", [
  "#1d1f21", "#cc6666", "#b5bd68", "#f0c674", "#81a2be", "#b294bb", "#8abeb7", "#c5c8c6",
  "#666666", "#d54e53", "#b9ca4a", "#e7c547", "#7aa6da", "#c397d8", "#70c0b1", "#eaeaea",
]);

// Base themes: light and dark pairs shown first in Settings.
export const BASE_THEMES = [
  ["Catppuccin Latte", "Catppuccin Mocha"],
  ["Atom One Light", "Atom One Dark"],
  ["Gruvbox Light", "Gruvbox Dark"],
];

// A theme without a pair that the user already has in the config.
export const BASE_SINGLES = ["Dracula"];

export const THEME_NAMES = Object.keys(THEME_DATA);
const cache = new Map();

function build([bg, fg, cursor, selBg, selFg, pal]) {
  const hex = (h) => `#${h}`;
  const colors = Array.from({ length: 16 }, (_, i) => hex(pal.slice(i * 6, i * 6 + 6)));
  return theme(
    hex(bg), hex(fg), hex(cursor || fg),
    selBg ? hex(selBg) : mix(hex(bg), hex(fg), 0.3),
    colors,
    selFg ? hex(selFg) : hex(fg),
  );
}

// Unknown names fall back to the default theme, as Ghostty does for a missing file.
export function themeFor(name) {
  if (!name || !Object.hasOwn(THEME_DATA, name)) return DEFAULT;
  if (!cache.has(name)) cache.set(name, build(THEME_DATA[name]));
  return cache.get(name);
}
